SELECT login_id
FROM tb_login_account
WHERE tenant_id = #{tenantId}
  AND login_code = #{loginCode}
LIMIT 1

SELECT user_id
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND login_id = #{loginId}
LIMIT 1

SELECT login_id
FROM (
  SELECT la.login_id
  FROM tb_login_account la
  WHERE la.tenant_id = #{tenantId}
    AND la.login_id = #{candidateId}
  UNION ALL
  SELECT u.login_id
  FROM tb_user u
  WHERE u.tenant_id = #{tenantId}
    AND u.user_id = #{candidateId}
) q
LIMIT 1

SELECT login_id
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND exe_seq = #{exeSeq}
  AND COALESCE(muldec_status, '') = 'drafted'
  AND arrival_at IS NOT NULL
  AND exe_at IS NULL
LIMIT 1

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND COALESCE(muldec_status, '') = 'drafted'

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
AND electronic_approval_id = #{approvalId}

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND COALESCE(muldec_status, '') = 'drafted'
  AND COALESCE(app_status, '') IN ('approved', 'returned')

SELECT MAX(exe_seq)
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND login_id = #{loginId}
  AND COALESCE(muldec_status, '') = 'drafted'
  AND COALESCE(app_status, '') IN ('approved', 'returned')

SELECT login_id
FROM tb_electronic_approval_line_info
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{approvalId}
  AND login_id = #{loginId}
  AND COALESCE(muldec_status, '') = 'cooperated'
  AND arrival_at IS NOT NULL
  AND exe_at IS NULL
LIMIT 1

SELECT COALESCE(MAX(answer_seq), 0) + 1
FROM tb_electronic_approval_history_main
WHERE tenant_id = #{tenantId}
  AND electronic_approval_line_id = #{electronicApprovalLineId}
  AND exe_seq = #{exeSeq}

