UPDATE tb_electronic_approval_history_main
SET answer_cnt = #{comment},
    answer_type_name = 'USER'
WHERE tenant_id = #{tenantId}
  AND electronic_approval_history_id = #{commentId}
  AND created_by = #{actorLoginId}
  AND answer_type_name = 'USER'

UPDATE tb_electronic_approval_history_main
SET answer_cnt = '사용자에 의해 삭제 되었습니다.',
    answer_type_name = 'DELETED'
WHERE tenant_id = #{tenantId}
  AND electronic_approval_history_id = #{commentId}
  AND created_by = #{actorLoginId}
  AND answer_type_name = 'USER'

