UPDATE tb_document_attachment_upload_session SET session_status = #{sessionStatus}, attachment_id = #{attachmentId, jdbcType=BIGINT}, completed_at = #{completedAt, jdbcType=TIMESTAMP}, updated_by = #{updatedBy, jdbcType=BIGINT}, updated_at = NOW() WHERE tenant_id = #{tenantId} AND upload_token = #{uploadToken}
AND session_status = #{expectedSessionStatus}
AND expires_at > NOW()

UPDATE tb_document_attachment_upload_session
SET session_status = 'CLEANED',
    updated_by = #{updatedBy, jdbcType=BIGINT},
    updated_at = NOW()
WHERE tenant_id = #{tenantId}
  AND upload_token = #{uploadToken}
